import{_ as t,C as r,o,c as i,E as n,a2 as s}from"./chunks/framework.Cm6XCzck.js";const _=JSON.parse('{"title":"持久工作不等于执行权","description":"","frontmatter":{"title":"持久工作不等于执行权","date":"2026-08-14","column":"digital-employee","category":"daily","article_type":"engineering-insight","edition":"research-center","research_question":"How should long-lived digital employees preserve pending work across interruption and restart without turning persistence itself into permission to execute?","summary":"持久队列只解决工作身份存续这一类可靠性问题。安全的自主恢复还需要把执行准入、恢复授权、所有权以及外部副作用保护分别建模。","sources":["research/analysis/Q-20260814-01-durable-work-identity-execution-authority.md","research/reading/Q-20260814-01-persistent-thread-queue-dispatch-boundary.md"],"item_id":"Q-20260814-01","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-14-durable-work-execution-authority-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/digital-employee/2026-08-14-durable-work-execution-authority.md","filePath":"zh/digital-employee/2026-08-14-durable-work-execution-authority.md","lastUpdated":1786725312000}'),l={name:"zh/digital-employee/2026-08-14-durable-work-execution-authority.md"};function p(d,e,u,h,c,g){const a=r("ArticleCover");return o(),i("div",null,[n(a,{image:"/assets/covers/daily-2026-08-14-durable-work-execution-authority-cover.png",kicker:"数字员工 · 每日研究",title:"持久工作不等于执行权",summary:"持久队列只解决工作身份存续这一类可靠性问题。安全的自主恢复还需要把执行准入、恢复授权、所有权以及外部副作用保护分别建模。",version:"Q-20260814-01",status:"Daily Runtime V5 · 2026-08-14",languageHref:"/en/digital-employee/2026-08-14-durable-work-execution-authority",languageLabel:"English"}),e[0]||(e[0]=s('<h1 id="持久工作不等于执行权" tabindex="-1">持久工作不等于执行权 <a class="header-anchor" href="#持久工作不等于执行权" aria-label="Permalink to &quot;持久工作不等于执行权&quot;">​</a></h1><p>长期运行的数字员工有一个看似简单的可靠性问题：进程被中断、用户断开连接或工作进程重启以后，尚未完成的工作怎么办？最直接的答案是持久化——把工作保存下来，之后再恢复。</p><p>这个答案是必要的，却并不完整。一个持久记录只能说明工作<strong>仍然存在</strong>，不能说明某个执行者<strong>现在就被允许继续执行</strong>。</p><p>2026-08-14 的研究对象分析了 Codex 中一个已经合并的按线程持久队列实现。该实现为排队提交保留稳定身份，按线程持久化，并且直到核心真正接纳一次执行后才移除队列项；当线程处于中断状态时，它还会主动抑制自动派发，并提供显式的操作者恢复入口。这些只是特定实现中的有界事实，并不能证明一种通用的数字员工架构，但它们暴露出一个重要的工程边界。</p><h2 id="三个事实不能合并成一个事实" tabindex="-1">三个事实不能合并成一个事实 <a class="header-anchor" href="#三个事实不能合并成一个事实" aria-label="Permalink to &quot;三个事实不能合并成一个事实&quot;">​</a></h2><p>可靠的智能体运行环境至少需要区分三件事。</p><p>第一是<strong>工作身份</strong>：待办工作存在，拥有稳定身份，并且能够跨越会话或进程边界。第二是<strong>执行准入</strong>：调度者已经根据当前条件判断，这项工作可以被某个执行者消费。第三是<strong>恢复授权</strong>：之前的暂停、中断、预算停止或策略停止，已经按照相应规则被明确解除。</p><p>持久化解决的是第一件事。它不能自动替代第二件和第三件。</p><p>所分析的实现通过两个机制体现了这种分离。其一，队列项只有在核心返回已经启动后才删除，这比“先删队列、再尝试执行”缩小了工作丢失窗口。其二，中断状态不会被当成普通空闲状态处理：系统不会因为执行者空闲就自动继续，而是等待显式的启动动作解除策略边界。</p><p>真正值得关注的并不是某个具体队列接口，而是：<strong>存储状态与许可状态属于不同种类的状态</strong>。</p><h2 id="为什么-空闲就继续-并不安全" tabindex="-1">为什么“空闲就继续”并不安全 <a class="header-anchor" href="#为什么-空闲就继续-并不安全" aria-label="Permalink to &quot;为什么“空闲就继续”并不安全&quot;">​</a></h2><p>以吞吐量为中心的调度器很容易把所有空闲执行者视为可用，然后立即清空其队列。这样可以降低延迟，也能让计算资源保持繁忙，但它会抹掉“当前没有任务执行”和“当前已经获得继续执行许可”之间的差别。</p><p>当系统经历了人工停止、安全中断、预算耗尽或策略决定时，这两个状态显然不等价。此时，待办工作之所以需要继续持久保存，恰恰可能是因为它<strong>暂时不应该运行</strong>。</p><p>这也说明，失败分类属于派发策略，而不是存储逻辑。有些失败可以合理地自动继续，有些则必须经过人工或策略授权。队列本身不应仅凭“记录存在且执行者空闲”推导出答案。</p><h2 id="准入后再删除更可靠-但不是-恰好一次" tabindex="-1">准入后再删除更可靠，但不是“恰好一次” <a class="header-anchor" href="#准入后再删除更可靠-但不是-恰好一次" aria-label="Permalink to &quot;准入后再删除更可靠，但不是“恰好一次”&quot;">​</a></h2><p>所分析的机制还展示了另一个边界：在执行核心确认启动之前保留持久队列项，确实比提前删除更可靠，因为队列在明确的准入事件发生前仍然保持权威。</p><p>但这仍然不能建立“恰好一次完成”的保证。崩溃完全可能发生在准入之后、持久完成之前。如果外部工具、接口、文件或其他系统已经发生改变，恢复时重新执行同一项工作就可能重复产生副作用。</p><p>因此，现有证据只支持一个局部结论：准入后删除改善了交接边界。它没有证明分布式所有权、跨进程互斥，也没有证明外部副作用具备幂等性。</p><h2 id="多执行者环境还缺少一层所有权" tabindex="-1">多执行者环境还缺少一层所有权 <a class="header-anchor" href="#多执行者环境还缺少一层所有权" aria-label="Permalink to &quot;多执行者环境还缺少一层所有权&quot;">​</a></h2><p>所选队列使用的是进程内串行化。这在单一进程内部有明确价值，但当多个执行者或多个主机都可能消费同一个持久队列时，它不再足够。</p><p>此时，运行环境还需要独立的所有权机制，例如租约、隔离令牌、事务性声明，或其他跨进程排他机制。稳定的工作身份仍然重要，但它不会告诉系统“现在到底是哪一个执行者拥有执行权”。</p><p>恢复过程同样遵循这一原则。重启可以重新找到持久工作，却未必知道之前的执行者是否已经越过准入边界，更未必知道外部世界是否已经发生变化。因此，恢复所依赖的证据必须超出队列本身。</p><h2 id="工程含义-把权威显式建模" tabindex="-1">工程含义：把权威显式建模 <a class="header-anchor" href="#工程含义-把权威显式建模" aria-label="Permalink to &quot;工程含义：把权威显式建模&quot;">​</a></h2><p>对于长期运行的数字员工，一个更安全的语义链条是：</p><p><strong>工作存在 → 执行被准入 → 恢复获得授权 → 外部效果得到核对 → 完成被持久确认</strong>。</p><p>并不是每个系统都需要重型工作流引擎来实现这条链。对于单进程、低风险的助手，更简单的队列加自动派发可能完全是合理的工程取舍。协调机制的复杂度应与风险和并发模型匹配。</p><p>真正应该保持不变的是语义边界：持久化不能被当成执行许可证；空闲不能被当成恢复同意；本地串行化不能被描述成分布式所有权；执行已经启动也不能被描述成外部副作用已经“恰好一次”完成。</p><h2 id="运行层面的影响" tabindex="-1">运行层面的影响 <a class="header-anchor" href="#运行层面的影响" aria-label="Permalink to &quot;运行层面的影响&quot;">​</a></h2><p>这种分离会直接影响运行环境的设计与可观测性。工作记录应独立于界面连接和工作进程会话保留稳定身份；执行准入事件应可明确记录和审计；暂停与中断状态应携带清晰的恢复规则，而不是折叠成普通空闲；多执行者系统应保存所有权或租约证据；恢复时还应能够判断某个外部效果是否可能已经发生。</p><p>这些要求并不是为了制造更多状态，而是为了避免某一种状态承担它实际上并不拥有的权威。</p><h2 id="证据边界" tabindex="-1">证据边界 <a class="header-anchor" href="#证据边界" aria-label="Permalink to &quot;证据边界&quot;">​</a></h2><p>本文证据来自一个实验性的 Codex 按线程队列实现及其测试。它属于公开实现事实，但不是对通用数字员工调度架构的独立验证。来源没有建立分布式共识、跨进程互斥、优先级、截止时间、依赖调度、服务等级策略，也没有建立外部副作用的恰好一次语义。</p><p>因此，可支持的结论应保持有界：这一实现展示了“持久工作身份、执行准入、恢复授权”三者分离的一个有力本地版本；分布式所有权以及副作用安全恢复所需的额外层仍然是开放的工程问题。</p><h2 id="仍待回答的问题" tabindex="-1">仍待回答的问题 <a class="header-anchor" href="#仍待回答的问题" aria-label="Permalink to &quot;仍待回答的问题&quot;">​</a></h2><p>当多个执行者可能消费同一个线程时，怎样的租约与隔离模型才足够？哪些失败类型应该自动恢复，哪些必须经过显式授权？从执行准入到持久完成之间，哪些证据必须跨崩溃保留下来，才能避免恢复时重复外部副作用？</p><p>这些问题恰恰从持久化能够解决的范围之外开始。也正因如此，持久化应被视为可靠性的基础能力，而不是行动许可。</p>',36))])}const b=t(l,[["render",p]]);export{_ as __pageData,b as default};
